for (name, signature, explanation) in (
    (:WireRequest, "WireRequest(method, url, headers, body)", "Hold a built HTTP request: strings for method/URL, string pairs for headers and a byte-vector body. Default display withholds sensitive details, but explicit fields can expose credentials and prompts. Creating or inspecting this object does not send it."),
    (:HttpResponse, "HttpResponse(; status, headers=Pair{String,String}[], body=UInt8[])", "Represent HTTP status, string-pair headers and body bytes. In open_response's streaming callback, the head has an empty body and the live bytes come from the IO argument. This is distinct from canonical Response."),
    (:build_request, "build_request(client::ProviderLM, request::Request; stream=false)", "Build a WireRequest for the configured protocol. Resolve credentials once for this built request, validate provider mappings and read any local media paths. Does not send the model request, but credential callbacks/cloud acquisition may perform I/O. Use synthetic static credentials for offline fixtures."),
    (:parse_response, "parse_response(client::ProviderLM, request::Request, response::HttpResponse)", "Parse one buffered provider response into canonical Response. HTTP errors raise normalized exceptions; malformed response bodies can fail parsing. Uses the configured protocol and original request context without sending another request."),
    (:normalize_error, "normalize_error(client::ProviderLM, status, body)", "Convert a provider HTTP failure into an LM15Error using its status and raw response text. This returns an exception value and performs no network request. Provider text may be sensitive."),
    (:build_models_request, "build_models_request(client::ProviderLM)", "Build a model-listing WireRequest. Resolves credentials and checks declared endpoint support but does not send the listing request."),
    (:parse_models_response, "parse_models_response(client::ProviderLM, response::HttpResponse)", "Parse provider model-list data into ModelInfo values. Does not turn catalog metadata into live capability verification."),
    (:build_file_request, "build_file_request(client, operation::Symbol; request=nothing, id=nothing, limit=20, cursor=nothing)", "Build upload/get/list/delete/download file operations. Upload takes FileUploadRequest and can read a local file and buffer multipart bytes. Credentials are resolved, but the resulting WireRequest is not sent."),
    (:parse_file_response, "parse_file_response(client, response::HttpResponse; page=false)", "Parse FileInfo, or FilePage when page=true. Downloads use their raw byte body instead of this metadata parser."),
    (:build_cache_request, "build_cache_request(client, operation::Symbol; prefix=nothing, id=nothing, ttl_seconds=nothing, label=nothing, limit=20, cursor=nothing)", "Build a stored-cache create/get/list/update/delete request. Creation uses a Request prefix; supported mappings are explicit. Resolves credentials without sending the cache operation."),
    (:parse_cache_response, "parse_cache_response(client, response::HttpResponse; page=false)", "Parse stored-cache metadata as CacheInfo or CachePage. No provider operation is performed by parsing."),
    (:build_generation_request, "build_generation_request(client, request::Union{ImageGenerationRequest,SpeechGenerationRequest})", "Build an image or speech WireRequest. Input images can require local file reads; credentials may trigger acquisition. Does not submit generation."),
    (:parse_generation_response, "parse_generation_response(client, request::Union{ImageGenerationRequest,SpeechGenerationRequest}, response::HttpResponse)", "Parse an image or speech response using the original request type. Return ImageGenerationResponse or SpeechGenerationResponse. Media is materialized in memory."),
    (:build_batch_requests, "build_batch_requests(client, action::Symbol; request=nothing, id=nothing, limit=20, upload_body=nothing, status_body=nothing)", "Build one batch phase: :upload, :submit, :status, :list, :cancel or :result_fetches. Return Vector{WireRequest}, possibly empty for inline uploads/results. request is BatchRequest for upload/submit; submission can require the parsed upload_body object, while result_fetches uses parsed status_body. Resolve credentials but do not send these requests. Prefer batch for application code."),
    (:parse_batch_response, "parse_batch_response(client, response::HttpResponse; list=false)", "Parse one batch status/submission response, or a list of BatchJobInfo values when list=true. No polling occurs."),
    (:parse_batch_entries, "parse_batch_entries(client, status_body, fetched)", "Return BatchEntry values from a parsed status object and a sequence of fetched JSONL text strings. Gemini reads inline entries from status_body instead. Entries retain zero-based input indices; duplicate/out-of-range file-result indices are rejected and missing entries are represented explicitly. This parser performs no downloads."),
    (:build_video_requests, "build_video_requests(client, action::Symbol; request=nothing, id=nothing, status_body=nothing, limit=20, model=nothing)", "Build a :submit, :status, :list or :result_fetch phase as Vector{WireRequest}. Submission takes VideoGenerationRequest; result_fetch takes parsed status_body and can return an empty vector for a URL-only result. Gemini listing needs a model; xAI listing is refused. Resolve credentials without sending the requests. Prefer video_generate/video_result in application code."),
    (:parse_video_response, "parse_video_response(client, response::HttpResponse; list=false, id=nothing)", "Parse VideoJobInfo, or a list of those snapshots. id can supply context for protocols whose status response omits it."),
    (:parse_video_part, "parse_video_part(client, status_body, fetched)", "Return VideoPart from a parsed status object. xAI reads the result URL and needs no fetched response; other mappings require fetched::HttpResponse with the materialized media and a Content-Type. This function performs no download itself."),
    (:live_setup_frames, "live_setup_frames(client::ProviderLM, config::LiveConfig)", "Build provider setup frames for a live session. Validate feature/format support without opening the socket. The live entry point handles the actual connection and authentication."),
    (:encode_live_event, "encode_live_event(client::ProviderLM, config::LiveConfig, event::LiveClientEvent)", "Return provider JSON frame objects for a canonical outgoing event. One event may produce multiple frames; encoding does not send them."),
    (:decode_live_frame, "decode_live_frame(client::ProviderLM, raw)", "Parse a provider text/byte frame into zero or more LiveServerEvent values. No socket receive is performed. Keep incomplete tool fragments distinct from complete calls."),
    (:request_from_openai_chat, "request_from_openai_chat(body::AbstractDict; compat=nothing)\n    request_from_openai_chat(client::ProviderLM, body::AbstractDict)\n    request_from_openai_chat(router, model, messages; kwargs...)", "Import Chat-style data into canonical Request, refusing unrepresentable fields rather than dropping them. The router form returns (request, client), may resolve credentials, and rejects transport/credential/retry settings mixed into request keywords. It does not submit generation."),
    (:response_from_openai_chat, "response_from_openai_chat(body; model=nothing, choice=nothing)", "Parse an already available Chat-style response body into Response. model can fill missing response context; choice is a zero-based index and must be supplied for multiple choices. No network request is performed."),
    (:openai_chat_model_string, "openai_chat_model_string(model::AbstractString)", "Translate known foreign provider/model spellings into provider:model. Already colon-prefixed names are retained. Unknown slash prefixes raise UnknownModelError rather than guessing."),
    (:resolve_openai_chat, "resolve_openai_chat(router, model)", "Resolve a migrated Chat-style model name. An implicit OpenAI family rule selects openai-chat; explicit provider prefixes retain their meaning. Returns Resolution, without submitting a request."),
    (:complete_from_openai_chat, "complete_from_openai_chat(router, model, messages; kwargs...)", "Import Chat-style arguments, obtain the selected client and submit complete. This contacts a provider and can incur charges. Client options belong in RouterConfig, not request kwargs."),
    (:stream_from_openai_chat, "stream_from_openai_chat(router, model, messages; kwargs...)", "Import Chat-style arguments and return the selected client's lazy canonical event stream. Own and close it explicitly; there is no hidden retry or conversation loop."),
    (:token_exchange_build, "token_exchange_build(provider, rung, inputs, context::ChainContext)", "Advanced conformance helper: produce deterministic form-exchange data for supported GCP ADC/service-account and Azure environment rungs. It can create secret-bearing assertions using context material, but does not send the exchange. Unsupported rungs are explicit refusals."),
    (:token_exchange_parse, "token_exchange_parse(provider, rung, status, body, context::ChainContext)", "Parse a cloud exchange result into AwsCredentials or BearerToken. Credential-process status is an exit code; other statuses are HTTP statuses. Reject failed acquisition instead of choosing a different account. No network call occurs."),
    (:sigv4_sign, "sigv4_sign(method, url, headers, body, credentials::AwsCredentials, region, service; now=time())", "Compute AWS Signature Version 4 material locally. Return signing metadata including signed headers; no request is sent. Inputs and results can expose credentials, URLs or payload information. Normal application requests use the configured cloud client instead."),
)
    doc = "    " * signature * "\n\n" * explanation
    @eval @doc $doc $name
end
